using System.Net;
using System.Text.Json;
using Htt.Host.Api.Accounting;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class BankRuleTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();private static int serial;
 public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static string Status(JsonElement p)=>p.GetProperty("snapshot").GetProperty("status").GetString()!;
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 private async Task<BankRuleInput> Input(HttpClient c,string kind="PAY",bool taxable=false,string basis="NON_CASH")
 {
  await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);
  var bank=await Create(c,"/bank-accounts",new BankAccountInput(Code(),"Rule bank","BANK","123456",(20000000+Interlocked.Increment(ref serial)).ToString(),"HTT"));
  var account=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@c,@code,'Rule offset',@kind)RETURNING id",("c",db.Company),("code",Code()),("kind",kind=="PAY"?"EXPENSE":"REVENUE")))!;
  var tax=(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@c AND code=@code",("c",db.Company),("code",taxable?"GST":"N-T")))!;
  return new("Service charges",bank,kind,10,true,"SUGGEST",new("DESCRIPTION","CONTAINS","service"),[new(account,tax,"Service",kind=="PAY"?"NON_CAPITAL":taxable?"TAXABLE":"EXCLUDED",RecoverablePercent:kind=="PAY"&&taxable?100:0)]);
 }
 private async Task<(Guid Statement,Guid Line)> Statement(HttpClient c,BankRuleInput x,decimal gross=110,string description="Service charge",DateOnly? on=null,string reference="BANK-REF")
 {var day=on??await Today();var amount=x.Kind=="PAY"?-gross:gross;var a=await Expect(await Send(c,HttpMethod.Post,$"/bank-accounts/{x.BankAccountId}/statements/import",new BankStatementImportInput(Code(),day,day,0,amount,[new(day,amount,description,reference)])),HttpStatusCode.Created);return(Id(a.GetProperty("statement")),Id(a.GetProperty("lines")[0]));}
 private static Task<HttpResponseMessage> Save(HttpClient c,BankRuleInput x,Guid? id=null,long? version=null,string? key=null)=>Send(c,id.HasValue?HttpMethod.Put:HttpMethod.Post,id.HasValue?$"/bank-rules/{id}":"/bank-rules",x,version,key);
 private async Task<JsonElement> Preview(HttpClient c,Guid line,bool evidence=false,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,$"/bank-statement-lines/{line}/rule-preview",new BankRulePreviewInput(evidence?"SOURCE-INVOICE":null,evidence?await Today():null),key:key),HttpStatusCode.Created);
 private static Task<HttpResponseMessage> Execute(HttpClient c,Guid preview,string? key=null,bool confirm=true,string reason="Reviewed source; no prior invoice or posting")=>Send(c,HttpMethod.Post,$"/bank-rule-previews/{preview}/execute",new BankRuleExecuteInput(confirm,reason),key:key);
 private async Task<long> Sources()=>(long)(await S("SELECT count(*)FROM accounting.bank_transactions WHERE company_id=@c",("c",db.Company)))!;
 [Theory][InlineData("PAY",false,"CASH")][InlineData("PAY",true,"CASH")][InlineData("PAY",true,"NON_CASH")][InlineData("RECEIVE",false,"NON_CASH")][InlineData("RECEIVE",true,"CASH")][InlineData("RECEIVE",true,"NON_CASH")]
 public async Task Controlled_execution_uses_C01_once_and_preserves_GST_cashflow_and_ledger(string kind,bool taxable,string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c,kind,taxable,basis);await Expect(await Save(c,x),HttpStatusCode.Created);var st=await Statement(c,x);var p=await Preview(c,st.Line,taxable&&kind=="PAY");Assert.Equal("READY",Status(p));Assert.Equal(0,await Sources());var e=await Expect(await Execute(c,Id(p)),HttpStatusCode.Created);var source=await Get(c,$"/bank-transactions/{e.GetProperty("sourceDocumentId").GetGuid()}");Assert.Single(source.GetProperty("activeMatches").EnumerateArray());Assert.Equal(110,D(source.GetProperty("transaction").GetProperty("gross")));Assert.Equal(taxable?10:0,D(source.GetProperty("lines")[0].GetProperty("tax")));await FinancialReportAssertions.Check(c);await Expect(await Send(c,HttpMethod.Post,$"/bank-statements/{st.Statement}/reconcile",new BankReconcileInput(Code(),"zero difference"),2),HttpStatusCode.Created);await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Priority_ties_block_execution_and_disabled_rule_is_ignored()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var a=await Expect(await Save(c,x),HttpStatusCode.Created);var b=await Expect(await Save(c,x with{Name="Another"}),HttpStatusCode.Created);var st=await Statement(c,x);var p=await Preview(c,st.Line);Assert.Equal("AMBIGUOUS_RULE",Status(p));await Expect(await Execute(c,Id(p)),HttpStatusCode.Conflict);await Expect(await Save(c,x with{Enabled=false},Id(b),1),HttpStatusCode.OK);p=await Preview(c,st.Line);Assert.Equal(Id(a),p.GetProperty("snapshot").GetProperty("selectedRuleId").GetGuid());await Expect(await Save(c,x with{Priority=1,Enabled=true},Id(b),2),HttpStatusCode.OK);p=await Preview(c,st.Line);Assert.Equal(Id(b),p.GetProperty("snapshot").GetProperty("selectedRuleId").GetGuid());await Expect(await Execute(c,Id(p)),HttpStatusCode.Created);}
