 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);if(value=="%")value="%%";await Expect(await Save(c,x with{Condition=new(field,op,value)}),HttpStatusCode.Created);var st=await Statement(c,x,description:description);Assert.Equal(hit?"READY":"NO_RULE",Status(await Preview(c,st.Line)));}
