 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);x=x with{Lines=[x.Lines[0]with{Percent=33.3333m},x.Lines[0]with{Percent=66.6667m,CashFlowCategory="INVESTING"}]};await Expect(await Save(c,x),HttpStatusCode.Created);var st=await Statement(c,x,100);var p=await Preview(c,st.Line);var rows=p.GetProperty("snapshot").GetProperty("lines").EnumerateArray().ToArray();Assert.Equal(33.33m,D(rows[0].GetProperty("net")));Assert.Equal(66.67m,D(rows[1].GetProperty("net")));await Expect(await Execute(c,Id(p)),HttpStatusCode.Created);await FinancialReportAssertions.Check(c);}
