 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var rule=Id(await Expect(await Save(c,x),HttpStatusCode.Created));var st=await Statement(c,x);var p=await Preview(c,st.Line);
 if(change=="priority")await Expect(await Save(c,x with{Priority=11},rule,1),HttpStatusCode.OK);if(change=="disable")await Expect(await Save(c,x with{Enabled=false},rule,1),HttpStatusCode.OK);if(change=="new-rule")await Expect(await Save(c,x with{Priority=99}),HttpStatusCode.Created);if(change=="account")await S("UPDATE accounting.accounts SET name='Renamed' WHERE company_id=@c AND id=@a",("c",db.Company),("a",x.Lines[0].AccountId));if(change=="tax-code")await S("UPDATE accounting.tax_codes SET name='Renamed tax' WHERE company_id=@c AND id=@t",("c",db.Company),("t",x.Lines[0].TaxCodeId));if(change=="statement")await Expect(await Send(c,HttpMethod.Post,$"/bank-statements/{st.Statement}/void",new BankClearingChangeInput(Code(),"bad import"),1),HttpStatusCode.OK);
 await Expect(await Execute(c,Id(p)),HttpStatusCode.Conflict);Assert.Equal(0,await Sources());}
 [Theory][InlineData("save")][InlineData("preview")][InlineData("execute")]
 public async Task Idempotent_replay_is_stable_and_changed_payload_conflicts(string operation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var st=await Statement(c,x);Guid pid=Guid.Empty;if(operation!="save")await Expect(await Save(c,x),HttpStatusCode.Created);if(operation=="execute")pid=Id(await Preview(c,st.Line));var key=Code();Task<HttpResponseMessage> Run(bool different=false)=>operation switch{"save"=>Save(c,x with{Name=different?"Changed":x.Name},key:key),"preview"=>Send(c,HttpMethod.Post,$"/bank-statement-lines/{st.Line}/rule-preview",new BankRulePreviewInput(different?"INV":null),key:key),_=>Execute(c,pid,key,reason:different?"Changed":"Reviewed")};var a=await Expect(await Run(),HttpStatusCode.Created);var b=await Expect(await Run(),HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,b));await Expect(await Run(true),HttpStatusCode.Conflict);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_execution_never_posts_twice(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);await Expect(await Save(c,x),HttpStatusCode.Created);var st=await Statement(c,x);var p=await Preview(c,st.Line);var key=Code();var all=await Task.WhenAll(Execute(c,Id(p),key),Execute(c,Id(p),sameKey?key:Code()));Assert.Equal(sameKey?2:1,all.Count(r=>r.StatusCode==HttpStatusCode.Created));if(!sameKey)Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1,await Sources());await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Concurrent_distinct_previews_for_same_line_compete_for_one_source()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);await Expect(await Save(c,x),HttpStatusCode.Created);var st=await Statement(c,x);var a=await Preview(c,st.Line);var b=await Preview(c,st.Line);var all=await Task.WhenAll(Execute(c,Id(a)),Execute(c,Id(b)));Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Created);Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1,await Sources());}
