 [Theory][InlineData(true)][InlineData(false)]public async Task Rule_edit_and_execution_serialize_in_both_orders(bool editFirst)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var rid=Id(await Expect(await Save(c,x),HttpStatusCode.Created));var st=await Statement(c,x);var p=await Preview(c,st.Line);await using var held=await db.SessionAsync();if(editFirst){await Sql.RowsAsync(held,"SELECT accounting.save_bank_rule(@id,1,@data::jsonb)",default,("id",rid),("data",JsonSerializer.Serialize(x with{Enabled=false},new JsonSerializerOptions(JsonSerializerDefaults.Web))));var run=Execute(c,Id(p));await Task.Delay(120);Assert.False(run.IsCompleted);await held.Transaction.CommitAsync();await Expect(await run,HttpStatusCode.Conflict);Assert.Equal(0,await Sources());}else{await Sql.RowsAsync(held,"SELECT accounting.execute_bank_rule(@id,true,'Reviewed')",default,("id",Id(p)));var edit=Save(c,x with{Enabled=false},rid,1);await Task.Delay(120);Assert.False(edit.IsCompleted);await held.Transaction.CommitAsync();await Expect(await edit,HttpStatusCode.OK);Assert.Equal(1,await Sources());}await FinancialReportAssertions.Check(c);}
