 [Theory][InlineData("save")][InlineData("preview")][InlineData("execute")]
 public async Task Late_audit_failure_rolls_back_all_effects_and_allows_same_key_retry(string action)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var st=await Statement(c,x);Guid pid=Guid.Empty;if(action!="save")await Expect(await Save(c,x),HttpStatusCode.Created);if(action=="execute")pid=Id(await Preview(c,st.Line));var key=Code();Task<HttpResponseMessage> Run()=>action switch{"save"=>Save(c,x,key:key),"preview"=>Send(c,HttpMethod.Post,$"/bank-statement-lines/{st.Line}/rule-preview",new BankRulePreviewInput(),key:key),_=>Execute(c,pid,key)};var ev=action switch{"save"=>"accounting.bank_rule_saved","preview"=>"accounting.bank_rule_previewed",_=>"accounting.bank_rule_executed"};await S($"CREATE FUNCTION accounting.test_c02_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='{ev}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c02_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_c02_failure()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(0,await Sources());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.bank_rule_executions WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c02_failure ON platform.audit_events;DROP FUNCTION accounting.test_c02_failure()");}await Expect(await Run(),HttpStatusCode.Created);}
