 private async Task<(Guid Period,DateOnly Day)> HistoricalCalendar()
 {var from=new DateOnly(2024,7,1);var year=(Guid)(await S("INSERT INTO accounting.fiscal_years(company_id,label,starts_on,ends_on,created_by)VALUES(@c,@ref,@a,@b,@actor)RETURNING id",("c",db.Company),("ref",Code()),("a",from),("b",from.AddYears(1)),("actor",db.Actor)))!;var period=(Guid)(await S("INSERT INTO accounting.periods(company_id,fiscal_year_id,starts_on,ends_on,created_by)VALUES(@c,@y,@a,@b,@actor)RETURNING id",("c",db.Company),("y",year),("a",from),("b",from.AddMonths(1)),("actor",db.Actor)))!;return(period,from);}
